from fabric import task

from benchmark.local import LocalBench
from benchmark.logs import ParseError, LogParser
from benchmark.recovery import RecoveryCsvPlotter, RecoveryError, RecoveryPlotter
from benchmark.utils import Print
from benchmark.plot import Ploter, PlotError
from benchmark.instance import InstanceManager
from benchmark.remote import Bench, BenchError


DEFAULT_RECOVERY_WINDOW = 5


@task
def local(ctx, debug=False, consensus_only=True, header_size=10_000_000, faults=0, f_num=3, crash_on_proposal=4):
    ''' Run benchmarks on localhost '''
    faults = int(faults)
    f_num = int(f_num)
    crash_on_proposal = int(crash_on_proposal) if faults > 0 else 0
    bench_params = {
        'faults': faults,
        'nodes': 10,
        'workers': 1,
        'rate': 100_000,
        'tx_size': 512,
        'duration': 60,
        "burst" : 50
    }
    node_params = {
        'consensus_only': consensus_only,
        'header_size': header_size,  # bytes
        'max_header_delay': 2_400,  # ms
        'gc_depth': 50,  # rounds
        'sync_retry_delay': 10_000,  # ms
        'sync_retry_nodes': 3,  # number of nodes
        'batch_size': header_size,  # bytescd
        'tx_size': bench_params['tx_size'],
        'max_batch_delay': 200,  # ms
        'f_num': f_num,
        'rs_block_size': 16 * 1024,  # bytes
        'rs_block_threads': 8,
        'crash_node_id': 0,
        'crash_on_proposal': crash_on_proposal,
    }
    try:
        ret = LocalBench(bench_params, node_params).run(debug, consensus_only)
        print(ret.result())
    except BenchError as e:
        Print.error(e)


@task
def create(ctx, nodes=2):
    ''' Create a testbed'''
    try:
        InstanceManager.make().create_instances(nodes)
    except BenchError as e:
        Print.error(e)


@task
def destroy(ctx):
    ''' Destroy the testbed '''
    try:
        InstanceManager.make().delete_instances()
    except BenchError as e:
        Print.error(e)


@task
def start(ctx):
    ''' Start at most `max` machines per data center '''
    try:
        InstanceManager.make().start_instances()
    except BenchError as e:
        Print.error(e)


@task
def stop(ctx):
    ''' Stop all machines '''
    try:
        InstanceManager.make().stop_instances()
    except BenchError as e:
        Print.error(e)


@task
def info(ctx):
    ''' Display connect information about all the available machines '''
    try:
        InstanceManager.make().print_info()
    except BenchError as e:
        Print.error(e)


@task
def install(ctx):
    ''' Install the codebase on all machines '''
    try:
        Bench(ctx).install()
    except BenchError as e:
        Print.error(e)


@task
def remote(ctx, burst = 50, debug=False, consensus_only=True, header_size=10_000_000, faults=1, f_num=3, crash_on_proposal=6):
    ''' Run benchmarks on GCP '''
    faults = int(faults)
    f_num = int(f_num)
    crash_on_proposal = int(crash_on_proposal) if faults > 0 else 0
    bench_params = {
        'faults': faults,
        'nodes': 10,
        'workers': 1,
        'collocate': True,
        'rate': [100000],
        'tx_size': 512,
        'duration': 60,
        'runs': 1,
        'burst' : [burst],
    }

    nodes = bench_params['nodes']
    rate =  1000 * nodes * 20
    bench_params['rate'] = [rate]

    node_params = {
        'consensus_only': consensus_only,
        'header_size': header_size,  # bytes
        'max_header_delay': 5_000,  # ms
        'gc_depth': 50,  # rounds
        'sync_retry_delay': 10_000,  # ms
        'sync_retry_nodes': 3,  # number of nodes
        'batch_size': header_size,
        'tx_size': bench_params['tx_size'],  # bytes
        'max_batch_delay': 200,  # ms
        'leaders_per_round': 67,
        'f_num': f_num,
        'rs_block_size': 16 * 1024,  # bytes
        'rs_block_threads': 8,
        'crash_node_id': 0,
        'crash_on_proposal': crash_on_proposal,
    }
    try:
        Bench(ctx).run(bench_params, node_params, debug, consensus_only)
    except BenchError as e:
        Print.error(e)


@task
def plot(ctx):
    ''' Plot performance using the logs generated by "fab remote" '''
    plot_params = {
        'faults': [0],
        'nodes': [10, 20, 50],
        'workers': [1],
        'collocate': True,
        'tx_size': 512,
        'max_latency': [2_500, 4_500]
    }
    try:
        Ploter.plot(plot_params)
    except PlotError as e:
        Print.error(BenchError('Failed to plot performance', e))


@task
def recovery(ctx, directory='logs', committee='.committee.json', window=DEFAULT_RECOVERY_WINDOW, step=0.2, before=10.0, after=20.0, full=True, output='recovery-tps', label='Opt-Dispersed-Simple-IT'):
    ''' Plot sliding-window TPS over the full experiment by default. '''
    try:
        result = RecoveryPlotter(
            logs_dir=directory,
            committee_file=committee,
            window=float(window),
            step=float(step),
            before=float(before),
            after=float(after),
            full=full,
            output=output,
            label=label,
        ).run()
        if result['anchor_time'] is None:
            Print.info('TPS plot generated without a crash anchor')
        else:
            Print.info(
                f"Recovery plot anchored at crash round {result['anchor_round']} "
                f"for crashed node {result['faulty_author']}"
            )
        Print.info(f"CSV: {result['csv']}")
        Print.info(f"Plots: {', '.join(result['plots'])}")
    except RecoveryError as e:
        Print.error(BenchError('Failed to plot recovery TPS', e))


@task
def recovery_compare(ctx, csvs, labels='', colors='', output='recovery-tps-compare'):
    ''' Plot multiple recovery CSV files in one figure. '''
    try:
        plots = RecoveryCsvPlotter(
            csv_files=csvs.split(','),
            labels=labels.split(',') if labels else None,
            colors=colors.split(',') if colors else None,
            output=output,
        ).run()
        Print.info(f"Plots: {', '.join(plots)}")
    except RecoveryError as e:
        Print.error(BenchError('Failed to plot recovery comparison', e))


@task
def kill(ctx):
    ''' Stop execution on all machines '''
    try:
        Bench(ctx).kill()
    except BenchError as e:
        Print.error(e)


@task
def logs(ctx):
    ''' Print a summary of the logs '''
    try:
        print(LogParser.process('./logs', faults='?').result())
    except ParseError as e:
        Print.error(BenchError('Failed to parse logs', e))
